export const depotAssetSources={depotMountain:'assets/depot-mountain-face-v10.png',depotRoom:'assets/depot-room.png',depotManLeft:'assets/depot-uniformed-pair-v29.png',depotManRight:'assets/depot-uniformed-pair-v29.png',depotCrate:'assets/depot-crate.png'};
export const depotRequiredSlots=['depotRoom','depotCrate','depotManLeft','depotManRight'];
export function depotAssetState(sprites){const missing=depotRequiredSlots.filter(k=>!sprites[k]?.naturalWidth),failed=missing.filter(k=>sprites[k]?._loadError);return {ready:!missing.length,missing,failed,pending:missing.filter(k=>!failed.includes(k))}}
export function attachDepotAsset(im,src,changed,baseURL){const bundled=new URL(src,baseURL).href;im._bundledSource=bundled;im._loadError='';let recovered=false;im.onload=()=>{im._loadError='';changed()};im.onerror=()=>{if(!recovered){recovered=true;im.src=bundled+'?v=depot-v17';return}im._loadError='Failed to load '+src;changed()};im.src=bundled;return im}
const splitCache=new WeakMap();
export function depotFigureTexture(im,slot){if(!im?.naturalWidth||!im.src.includes('depot-uniformed-pair-v29.png'))return im;let halves=splitCache.get(im);if(!halves){halves=[0,1].map(i=>{const c=document.createElement('canvas');c.width=im.naturalWidth/2;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,i*c.width,0,c.width,c.height,0,0,c.width,c.height);return c});splitCache.set(im,halves)}return halves[slot==='depotManRight'?1:0]}
